    let dir = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-tmp-d9e4p2sr/"

    func testLongPress() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
